/**
 * bcrypt-PBKDF against OpenBSD's own output.
 *
 * The vectors are the three in `golang.org/x/crypto/ssh/internal/bcrypt_pbkdf`, whose header
 * records that they were generated by the OpenBSD reference implementation, plus the intermediate
 * `bcrypt_hash` value from the same file. Keeping the intermediate one matters: it isolates the
 * Blowfish half from the SHA-512 wrapping and the stride-interleaved output, so a failure says
 * which of the three is wrong instead of only that something is.
 *
 * The third vector's length is 88 bytes, which is not a multiple of 32 and therefore exercises the
 * partial final pass -- with stride 3, the three passes write 30, 29 and 29 bytes at offsets
 * 0/3/6..., 1/4/7... and 2/5/8..., and the `dest >= keyLength` break is what stops the last two
 * running off the end. A 32-byte-only test set would leave all of that uncovered.
 */
import { describe, expect, it } from "vitest";
import { sha512 } from "@noble/hashes/sha2.js";
import { bcryptHash, bcryptPbkdf, blowfishExpandState, blowfishInitState } from "@ocs/algos";

const hex = (bytes: Uint8Array): string => Buffer.from(bytes).toString("hex");
const utf8 = (text: string): Uint8Array => new TextEncoder().encode(text);
const noble = (data: Uint8Array): Uint8Array => Uint8Array.from(sha512(data));

const derive = (password: string, salt: string, rounds: number, length: number): string =>
  hex(bcryptPbkdf(noble, utf8(password), utf8(salt), rounds, length));

describe("bcryptHash", () => {
  it("matches the reference's intermediate value", () => {
    // pass = 0x00..0x3f, salt = 0x40..0x7f. Both are full 64-byte SHA-512 digests as far as the
    // primitive is concerned, which is all it ever sees.
    const password = Uint8Array.from({ length: 64 }, (_, i) => i);
    const salt = Uint8Array.from({ length: 64 }, (_, i) => i + 64);
    expect(hex(bcryptHash(password, salt))).toBe(
      "87904870eef9deddf8e7611a140106e6aaf1a363d9a2c504db356443721eb555",
    );
  });

  it("is not the same as running the salted expansion twice", () => {
    // The 64 loop expansions carry NO data -- only the first one is salted. Getting that wrong
    // gives a self-consistent function that matches nothing, so it is pinned directly.
    const password = Uint8Array.from({ length: 64 }, (_, i) => i);
    const salt = Uint8Array.from({ length: 64 }, (_, i) => i + 64);
    const wrong = blowfishInitState();
    blowfishExpandState(wrong, password, salt);
    blowfishExpandState(wrong, salt, salt);
    const right = blowfishInitState();
    blowfishExpandState(right, password, salt);
    blowfishExpandState(right, salt);
    expect(hex(new Uint8Array(right.p.buffer.slice(0)))).not.toBe(
      hex(new Uint8Array(wrong.p.buffer.slice(0))),
    );
  });
});

describe("bcryptPbkdf", () => {
  it("password/salt, 12 rounds, 32 bytes", () => {
    expect(derive("password", "salt", 12, 32)).toBe(
      "1ae42c05d487bc02f64921a4ebe4ea93bcacfe135fda99974c06b7b01fae149a",
    );
  });

  it("embedded NUL bytes are not a terminator", () => {
    // bcrypt truncates at a NUL; bcrypt-PBKDF cannot, because SHA-512 has already consumed the
    // whole string. This vector exists in the reference set for exactly that reason.
    expect(derive("passwordy\x00PASSWORD\x00", "salty\x00SALT\x00", 3, 32)).toBe(
      "7f310bd3e78c3280c59ce4595211a2928e8d4ec744c1ed2efc9f764e3388e0ad",
    );
  });

  it("non-ASCII password and salt, 88 bytes", () => {
    expect(derive("секретное слово", "посолить немножко", 8, 88)).toBe(
      "8df43fc6fe131fc47f0c9e39224bd94c70b6fcc8ee8135faddf61156e6cb2733" +
        "ea765f315a3e1e4afc35bf8687d189254c1e05a6fe80c0617f9183d67260d6a1" +
        "15c6c94e3603e2303fbb43a76a64523ffda686b1d4518543",
    );
  });

  it("a longer output is not an extension of a shorter one", () => {
    // The stride interleaving, stated as a property rather than left in a comment. PBKDF2 would
    // fail this test; that difference is the whole reason `keyLength` matters here.
    const short = derive("password", "salt", 4, 32);
    const long = derive("password", "salt", 4, 64);
    expect(long.startsWith(short)).toBe(false);
    // Only byte 0 survives: it is `out[0]` of the first pass either way, since `dest = 0` for
    // both strides. Byte 1 is `out[1]` at stride 1 and the *second* pass's `out[0]` at stride 2.
    expect(long.slice(0, 2)).toBe(short.slice(0, 2));
    expect(long.slice(2, 4)).not.toBe(short.slice(2, 4));
  });

  it("refuses what OpenBSD refuses", () => {
    expect(() => bcryptPbkdf(noble, utf8(""), utf8("salt"), 4, 32)).toThrow(/password/);
    expect(() => bcryptPbkdf(noble, utf8("pw"), utf8(""), 4, 32)).toThrow(/salt/);
    expect(() => bcryptPbkdf(noble, utf8("pw"), utf8("salt"), 0, 32)).toThrow(/round/);
    expect(() => bcryptPbkdf(noble, utf8("pw"), utf8("salt"), 4, 1025)).toThrow(/1024/);
  });
});
